I'm going to write a solver that builds an initial schedule from traffic counts, simulates it exactly, and improves it with a deterministic local search.

**Initial schedule.** For each intersection, count how many cars use each incoming street. A car's last street is excluded, because it is removed at the end of that street and never queues at the light. Streets with a nonzero count get a green slot of length 1, ordered by descending count. The order matters: streets with cars waiting at time 0 should come first.

**Simulation.**
- Each street has a queue of waiting cars.
- A car at the end of its street at time t joins the queue.
- At time t the light is green for the street whose slot contains t mod cycle.
- The first car in the queue crosses, at most one per second per street. Only one street is green at a time, so one car per intersection per second.
- The car then enters the next street and arrives at t + L.
- If that street is the car's last, it finishes at t + L, and scores F + D − T when T ≤ D.

Each second t from 0 to D, I process in order:
1. Arrivals at time t are added to the queues. A car that arrives at t and finds a green light crosses at t. Cars arriving at the same time are ordered by arrival time, then by car index. Only the initial cars have a defined order, so ties in the rest are broken by car index.
2. For each intersection with a schedule, the green street pops one car if its queue is non-empty. It is pushed into an arrival bucket at t + L of the next street, or scored if that is the last street.

Arrival buckets are indexed by time, so a bucket at time t is filled before processing t, because L ≥ 1. A car that arrives at t+L at the end of a non-last street is queued in the bucket at t+L and is processed in step 1 at that time.

Cost per simulation is about D plus the total number of car-street moves (up to 10^6), so roughly 10^6 operations. That allows a few hundred simulations in the time limit.

**Local search.** Until about 8 seconds have elapsed, repeatedly pick a random intersection (fixed-seed RNG) and apply one of two moves:
- swap two streets in its order, or
- change one street's duration by ±1 (minimum 1).

Evaluate by full simulation. Keep the change if the score does not decrease, otherwise revert. To keep this deterministic I bound the loop by an iteration count rather than wall time, calibrated by the first simulation's cost: iterations = budget / measured work, where work is the number of simulated operations (not time). Concretely, the budget is about 3·10^8 operation units.

Only intersections with at least 2 scheduled streets are chosen for moves.

```cpp
#include <bits/stdc++.h>
using namespace std;

int D,I,S,V,F;
vector<int> sb,se,sl;
vector<vector<int>> path;
vector<vector<pair<int,int>>> sch; // per intersection: (street,dur)
long long opsCount;

long long simulate(){
    vector<vector<int>> cyc(I); // not used
    vector<int> cycleLen(I,0);
    vector<vector<int>> slot(I);
    for(int i=0;i<I;i++){
        int tot=0;
        for(auto&p:sch[i])tot+=p.second;
        cycleLen[i]=tot;
        slot[i].resize(tot);
        int k=0;
        for(auto&p:sch[i])for(int d=0;d<p.second;d++)slot[i][k++]=p.first;
    }
    vector<deque<int>> q(S);
    vector<int> pos(V,0);
    vector<vector<int>> bucket(D+1);
    for(int c=0;c<V;c++)q[path[c][0]].push_back(c);
    vector<int> active;
    for(int i=0;i<I;i++)if(cycleLen[i]>0)active.push_back(i);
    long long score=0;
    for(int t=0;t<=D;t++){
        for(int c:bucket[t])q[path[c][pos[c]]].push_back(c);
        opsCount+=bucket[t].size();
        for(int i:active){
            int s=slot[i][t%cycleLen[i]];
            if(q[s].empty())continue;
            int c=q[s].front();q[s].pop_front();
            pos[c]++;
            int ns=path[c][pos[c]];
            int at=t+sl[ns];
            if(at>D)continue;
            if(pos[c]==(int)path[c].size()-1){
                score+=F+D-at;
            } else bucket[at].push_back(c);
        }
        opsCount+=active.size();
    }
    return score;
}

int main(){
    scanf("%d %d %d %d %d",&D,&I,&S,&V,&F);
    sb.resize(S);se.resize(S);sl.resize(S);
    vector<string> name(S);
    unordered_map<string,int> id;
    char buf[64];
    for(int i=0;i<S;i++){
        scanf("%d %d %s %d",&sb[i],&se[i],buf,&sl[i]);
        name[i]=buf;id[name[i]]=i;
    }
    path.resize(V);
    vector<int> cnt(S,0);
    for(int c=0;c<V;c++){
        int p;scanf("%d",&p);
        path[c].resize(p);
        for(int j=0;j<p;j++){
            scanf("%s",buf);
            path[c][j]=id[buf];
            if(j<p-1)cnt[path[c][j]]++;
        }
    }
    sch.assign(I,{});
    vector<vector<int>> inc(I);
    for(int s=0;s<S;s++)if(cnt[s]>0)inc[se[s]].push_back(s);
    for(int i=0;i<I;i++){
        sort(inc[i].begin(),inc[i].end(),[&](int a,int b){
            if(cnt[a]!=cnt[b])return cnt[a]>cnt[b];
            return a<b;});
        for(int s:inc[i])sch[i].push_back({s,1});
    }
    opsCount=0;
    long long best=simulate();
    long long perSim=max(1LL,opsCount);
    long long iters=min(3000LL,max(0LL,300000000LL/perSim));
    vector<int> cand;
    for(int i=0;i<I;i++)if(sch[i].size()>=2)cand.push_back(i);
    mt19937 rng(12345);
    if(!cand.empty()){
        for(long long it=0;it<iters;it++){
            int i=cand[rng()%cand.size()];
            auto old=sch[i];
            int n=sch[i].size();
            if(rng()%2){
                int a=rng()%n,b=rng()%n;
                if(a==b)continue;
                swap(sch[i][a],sch[i][b]);
            } else {
                int a=rng()%n;
                if(rng()%2)sch[i][a].second++;
                else{
                    if(sch[i][a].second<=1)continue;
                    sch[i][a].second--;
                }
            }
            long long sc=simulate();
            if(sc>=best)best=sc;
            else sch[i]=old;
        }
    }
    int A=0;
    for(int i=0;i<I;i++)if(!sch[i].empty())A++;
    printf("%d\n",A);
    for(int i=0;i<I;i++){
        if(sch[i].empty())continue;
        printf("%d\n%d\n",i,(int)sch[i].size());
        for(auto&p:sch[i])printf("%s %d\n",name[p.first].c_str(),min(p.second,D));
    }
}
```

I have not compiled or run this, so it is untested against the sample.
